"use strict";
(() => {
  const project = 'https://dzxxjtmpcfsmvdgkcwvn.supabase.co';
  const key = 'sb_publishable_yTgQ5bw5pnSkNCTOH4me8Q_YaQhRkQ_';
  const endpoint = project + '/functions/v1/site-feedback';
  const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const labels = {error:'数値・内容の間違い',outdated:'古い情報',link:'リンク・画像の不具合',other:'その他',drop:'アイテムドロップ',def:'必要DEF',level:'モンスターLv',map:'出現場所',image:'ゲーム内画像',note:'備考・その他'};
  const states = {pending:'確認待ち',published:'公開済み',resolved:'対応済み',rejected:'見送り'};
  const date = value => new Date(value).toLocaleString('ja-JP');
  let dialog, active, adminClient, adminPromise, allCache, cacheTime = 0;
  const numberValue = (value,max) => value===''||value==null?null:(Number.isInteger(Number(value))&&Number(value)>=0&&Number(value)<=max?Number(value):null);
  function safeUrl(value){if(typeof value!=='string'||!value.trim())return '';try{const u=new URL(value);return u.protocol==='https:'?u.href:'';}catch{return '';}}
  function pageUrl(){const u=new URL(location.href);u.search='';return u.href;}
  function productionUrl(value){const u=new URL(value||pageUrl(),location.href);return 'https://yysupporttools.github.io/xen-rebirth-jp/'+u.pathname.split('/').pop()+u.hash;}
  function visitor(){try{let v=localStorage.getItem('xen-feedback-visitor-v1');if(!/^[a-f0-9-]{36}$/i.test(v||'')){v=crypto.randomUUID();localStorage.setItem('xen-feedback-visitor-v1',v);}return v;}catch{return crypto.randomUUID();}}
  async function request(action,payload,token){const headers={apikey:key};if(token)headers.Authorization='Bearer '+token;const options={headers,signal:AbortSignal.timeout(30000)};let url=endpoint;
    if(payload){options.method='POST';headers['Content-Type']='application/json';options.body=JSON.stringify({...payload,action});}
    else {const [operation,query]=action.split('&');url+='?action='+encodeURIComponent(operation)+(query?'&'+query:'');}
    const r=await fetch(url,options);const data=await r.json();if(!r.ok)throw Error(data.error||'通信できませんでした');return data;
  }
  function fields(d={}){return `<div class="report-field-grid"><label>モンスターLv<input name="level" type="number" min="0" max="300" value="${esc(d.level??'')}" placeholder="未確認なら空欄"></label><label>必要DEF・最小<input name="min_def" type="number" min="0" max="10000" value="${esc(d.min_def??'')}" placeholder="例：200"></label><label>必要DEF・最大<input name="max_def" type="number" min="0" max="10000" value="${esc(d.max_def??'')}" placeholder="範囲の目安がある場合"></label></div><p class="report-help">必要DEFは条件によって変わります。通常 / Hard、単体 / AoE、目標被ダメージなどの測定条件を備考に記載してください。</p><label>ドロップアイテム<textarea name="drop_items" maxlength="1200" placeholder="確認できたアイテムを1行ずつ記載">${esc(d.drop_items||'')}</textarea></label><label>出現場所<input name="map" maxlength="200" value="${esc(d.map||'')}" placeholder="地域・マップ名"></label><label>ゲーム内画像のURL<input name="image_url" type="url" maxlength="1000" value="${esc(d.image_url||'')}" placeholder="https://..."></label><label>備考・確認条件<textarea name="notes" maxlength="1000" placeholder="DEFの測定条件、ドロップ確認時の状況など">${esc(d.notes||'')}</textarea></label>`;}
  function readDetails(form){const data=new FormData(form);return {level:numberValue(data.get('level'),300),min_def:numberValue(data.get('min_def'),10000),max_def:numberValue(data.get('max_def'),10000),drop_items:String(data.get('drop_items')||''),map:String(data.get('map')||''),image_url:String(data.get('image_url')||''),notes:String(data.get('notes')||'')};}
  function makeDialog(){if(dialog)return dialog;dialog=document.createElement('dialog');dialog.className='report-dialog';dialog.setAttribute('aria-labelledby','xen-report-title');document.body.append(dialog);return dialog;}
  function open(options={}){active={kind:options.kind==='monster'?'monster':'article',title:String(options.title||options.monsterName||document.querySelector('main h1')?.textContent||document.title).trim().slice(0,200),url:productionUrl(options.url),monsterId:options.monsterId||''};
    const monster=active.kind==='monster';const el=makeDialog();el.innerHTML=`<div class="report-heading"><h2 id="xen-report-title">${monster?'モンスター情報を追記':'記事の修正を報告'}</h2><button type="button" class="report-close" aria-label="閉じる">×</button></div><p class="report-target">${esc(active.title)}</p><p class="report-help">${monster?'投稿は管理者の確認後、図鑑の「追加された情報」に掲載されます。':'報告は管理者に届きます。記事へは自動反映されません。'}</p><form class="report-form"><label>分類<select name="category">${(monster?['drop','def','level','map','image','note']:['error','outdated','link','other']).map(k=>`<option value="${k}">${labels[k]}</option>`).join('')}</select></label>${monster?fields(options.details):''}<label>${monster?'追記の要点':'間違っている箇所と正しい内容'}<textarea name="body" maxlength="3000" required placeholder="${monster?'例：このマップで○○のドロップを確認しました。':'どの箇所を、どのように修正するとよいか記載してください。'}"></textarea></label><label>出典・参考URL（任意）<input name="source_url" type="url" maxlength="1000" placeholder="https://..."></label><label>表示名（任意）<input name="author_name" maxlength="40" placeholder="匿名"></label><label>確認用画像（任意）<input name="attachment" type="file" accept="image/png,image/jpeg,image/webp"></label><p class="report-help">PNG / JPEG / WebP、2MB以内。添付画像は管理者のみ閲覧できます。個人情報やパスワードを含む画像は添付しないでください。ゲーム内画像として掲載したい場合は、画像URL欄を使用してください。</p><label class="report-honeypot" aria-hidden="true">ウェブサイト<input name="website" tabindex="-1" autocomplete="off"></label><p class="report-form-status" role="status" aria-live="polite"></p><div class="report-actions"><button type="button" class="report-cancel">キャンセル</button><button type="submit" class="primary">${monster?'確認用に送信':'報告を送信'}</button></div></form>`;
    el.querySelectorAll('.report-close,.report-cancel').forEach(b=>b.onclick=()=>el.close());el.querySelector('form').onsubmit=send;el.showModal();
  }
  async function readAttachment(file){if(!file?.size)return null;if(file.size>2097152||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('画像は PNG / JPEG / WebP、2MB以内で選んでください');const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(Error('画像を読み込めませんでした'));reader.readAsDataURL(file);});return {type:file.type,data:encoded};}
  async function send(event){event.preventDefault();const form=event.target,status=form.querySelector('.report-form-status'),button=form.querySelector('[type=submit]');button.disabled=true;status.textContent='送信しています…';
    try{const f=new FormData(form);const attachment=await readAttachment(f.get('attachment'));const result=await request('submit',{kind:active.kind,article_url:active.url,title:active.title,monster_id:active.monsterId,category:f.get('category'),body:f.get('body'),details:active.kind==='monster'?readDetails(form):{},source_url:f.get('source_url'),author_name:f.get('author_name'),attachment,visitor:visitor(),honeypot:f.get('website')});
      form.innerHTML=`<div class="report-success"><strong>送信しました</strong><p>${active.kind==='monster'?'管理者の確認後、追加情報として掲載します。':'管理者が内容を確認します。報告ありがとうございます。'}</p>${result.warning?`<p>${esc(result.warning)}</p>`:''}<p class="report-help">受付番号：${esc(result.id)}</p><button type="button">閉じる</button></div>`;form.querySelector('button').onclick=()=>dialog.close();
    }catch(e){status.textContent='送信できませんでした：'+e.message;button.disabled=false;}
  }
  async function loadAllMonsters(force=false){if(!force&&allCache&&Date.now()-cacheTime<30000)return allCache;const r=await fetch(project+'/rest/v1/monster_updates?select=*&order=updated_at.desc&limit=1000',{headers:{apikey:key},signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('追加情報を読み込めませんでした');allCache=await r.json();cacheTime=Date.now();return allCache;}
  async function loadMonster(id){return (await loadAllMonsters()).filter(row=>row.monster_id===id);}
  function detailHtml(d={}){const rows=[];if(d.level!=null)rows.push(['モンスターLv',d.level]);if(d.drop_items)rows.push(['ドロップアイテム',d.drop_items]);if(d.min_def!=null||d.max_def!=null)rows.push(['必要DEF',d.min_def!=null&&d.max_def!=null?`${d.min_def}～${d.max_def}`:d.min_def??d.max_def]);if(d.map)rows.push(['出現場所',d.map]);if(d.notes)rows.push(['備考・確認条件',d.notes]);return rows.length?`<dl class="report-published-fields">${rows.map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`:'';}
  async function mountMonster(container,monster){if(typeof container==='string')container=document.querySelector(container);if(!container)return;container.classList.add('monster-community');container.innerHTML='<div class="report-community-heading"><h3>追加された情報</h3><button type="button">情報を追記する</button></div><p class="report-community-status" role="status">読み込み中…</p><div class="report-community-list"></div>';container.querySelector('button').onclick=()=>open({kind:'monster',title:monster.name,monsterId:monster.id,url:monster.url||'monsters.html#'+monster.id});
    try{const rows=await loadMonster(monster.id);if(!container.isConnected)return;container.querySelector('.report-community-status').textContent=rows.length?'管理者が掲載を確認した投稿情報です。公式出典の情報とは区別して表示しています。':'追加情報はまだありません。ドロップやDEFなど、確認できた情報をお寄せください。';container.querySelector('.report-community-list').innerHTML=rows.map(r=>{const image=safeUrl(r.details?.image_url),source=safeUrl(r.source_url);return `<article class="report-published"><span class="report-tag">${esc(labels[r.category]||'追加情報')}</span><p>${esc(r.body)}</p>${detailHtml(r.details)}${image?`<a href="${esc(image)}" target="_blank" rel="noopener noreferrer"><img class="report-monster-image" src="${esc(image)}" alt="${esc(monster.name)}のゲーム内画像" loading="lazy"></a>`:''}<p class="report-help">${esc(r.author_name)} · ${date(r.updated_at)}${source?` · <a href="${esc(source)}" target="_blank" rel="noopener noreferrer">出典を確認 ↗</a>`:''}</p></article>`;}).join('');}catch(e){container.querySelector('.report-community-status').textContent=e.message+'。「情報を追記する」から投稿できます。';}}
  function button(options,label='修正を報告'){const b=document.createElement('button');b.type='button';b.className='xen-report-button';b.textContent=label;b.onclick=()=>open(typeof options==='function'?options():options);return b;}
  function ensureArticleButtons(){if(document.querySelector('#reports-admin'))return;const main=document.querySelector('main');if(!main)return;if(!main.querySelector('.article-report-tools')){const bar=document.createElement('div');bar.className='article-report-tools';bar.append(button(()=>({title:document.querySelector('#quest-detail h1')?.textContent||main.querySelector('h1')?.textContent||document.title}),'この記事の修正を報告'));const h=main.querySelector('h1');(h?.closest('.page-intro')||h)?.insertAdjacentElement('afterend',bar);if(!bar.isConnected)main.prepend(bar);}
    document.querySelectorAll('.glossary-entry[id]').forEach(entry=>{const links=entry.querySelector('.glossary-links');if(links&&!links.querySelector('.xen-report-button'))links.append(button({url:'glossary.html#'+encodeURIComponent(entry.id),title:entry.querySelector('.glossary-name-en')?.textContent||entry.id}));});
    const quest=document.querySelector('#quest-detail article.paper'),questId=location.hash.slice(1);if(quest&&/^[a-f0-9-]{36}$/i.test(questId)&&!quest.querySelector('.quest-report-tools')){const bar=document.createElement('div');bar.className='quest-report-tools article-report-tools';bar.append(button({url:'quests.html#'+questId,title:quest.querySelector('h1,h2')?.textContent||document.title},'このクエストの修正を報告'));quest.append(bar);}
  }
  function loadScript(src){return new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=new URL(src,location.href).href;script.onload=resolve;script.onerror=()=>reject(Error('ログイン機能を読み込めませんでした'));document.head.append(script);});}
  async function getAdminClient(){if(adminClient)return adminClient;if(!adminPromise)adminPromise=(async()=>{if(!window.supabase)await loadScript('assets/vendor/supabase.js');adminClient=window.supabase.createClient(project,key,{auth:{storageKey:'xen-board-admin',detectSessionInUrl:true}});return adminClient;})();return adminPromise;}
  async function adminSetup(){const root=document.getElementById('reports-admin');if(!root)return;const client=await getAdminClient(),login=document.getElementById('reports-login'),status=document.getElementById('reports-admin-status'),logout=document.getElementById('reports-logout'),filter=document.getElementById('reports-filter');
    const reload=async()=>{status.textContent='ログインを確認しています…';try{const {data:{session}}=await client.auth.getSession();login.hidden=!!session;logout.hidden=!session;if(!session){document.getElementById('reports-list').innerHTML='';status.textContent='管理者として登録されたメールアドレスでログインしてください。';return;}const {data,error}=await client.rpc('board_is_admin');if(error||!data)throw Error('このアカウントには管理者権限がありません');status.textContent='管理者としてログイン中';const result=await request('admin'+(filter.value?'&status='+encodeURIComponent(filter.value):''),null,session.access_token);renderAdmin(result.rows,session.access_token,reload);}catch(e){status.textContent=e.message;document.getElementById('reports-list').innerHTML='';}};
    login.onsubmit=async e=>{e.preventDefault();const b=login.querySelector('button');b.disabled=true;try{const email=new FormData(login).get('email');const {error}=await client.auth.signInWithOtp({email,options:{emailRedirectTo:new URL('reports.html',location.href).href}});if(error)throw error;status.textContent='ログインメールを送信しました。メールのリンクを開いてください。';}catch(e){status.textContent='送信できませんでした：'+e.message;}finally{b.disabled=false;}};logout.onclick=async()=>{await client.auth.signOut();await reload();};filter.onchange=reload;document.getElementById('reports-reload').onclick=reload;client.auth.onAuthStateChange(()=>setTimeout(reload,0));await reload();
  }
  function renderAdmin(rows,token,reload){const target=document.getElementById('reports-list');target.innerHTML=rows.length?rows.map(r=>`<article class="paper report-review"><p><span class="report-tag">${r.kind==='monster'?'モンスター追記':'記事修正'}</span> <span class="report-tag">${esc(states[r.status])}</span> ${esc(labels[r.category]||r.category)}</p><h2><a href="${esc(r.article_url)}" target="_blank" rel="noopener noreferrer">${esc(r.title)}</a></h2><p class="report-help">${esc(r.author_name)} · ${date(r.created_at)} · 受付番号 ${esc(r.id)}</p>${safeUrl(r.source_url)?`<p><a href="${esc(r.source_url)}" target="_blank" rel="noopener noreferrer">投稿者の出典URL ↗</a></p>`:''}${safeUrl(r.attachment_url)?`<p><a href="${esc(r.attachment_url)}" target="_blank" rel="noopener noreferrer">確認用画像を開く（管理者のみ・10分間有効）</a></p>`:''}<form data-review-id="${esc(r.id)}"><label>報告・追記の内容<textarea name="body" maxlength="3000" required>${esc(r.body)}</textarea></label>${r.kind==='monster'?`<details><summary>図鑑に掲載する数値・ドロップなどを編集</summary>${fields(r.details)}</details>`:''}<label>管理者メモ（公開されません）<textarea name="note" maxlength="500">${esc(r.review_note)}</textarea></label><label>状態<select name="status">${(r.kind==='monster'?['pending','published','rejected']:['pending','resolved','rejected']).map(s=>`<option value="${s}" ${s===r.status?'selected':''}>${states[s]}${s==='published'?'（図鑑の追記欄へ掲載）':''}</option>`).join('')}</select></label><p class="report-form-status" role="status"></p><button class="primary" type="submit">変更を保存</button></form></article>`).join(''):'<div class="paper"><p>この状態の報告はありません。</p></div>';
    target.querySelectorAll('[data-review-id]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('[type=submit]'),status=form.querySelector('.report-form-status');b.disabled=true;try{const f=new FormData(form);await request('review',{id:form.dataset.reviewId,status:f.get('status'),note:f.get('note'),body:f.get('body'),details:readDetails(form)},token);allCache=null;await reload();}catch(e){status.textContent='保存できませんでした：'+e.message;b.disabled=false;}});
  }
  window.XenReports={open,loadMonster,loadAllMonsters,mountMonster};
  function ready(){ensureArticleButtons();new MutationObserver(ensureArticleButtons).observe(document.querySelector('main')||document.body,{childList:true,subtree:true});const footer=document.querySelector('footer');if(footer&&!footer.querySelector('[href="reports.html"]')){const link=document.createElement('a');link.href='reports.html';link.textContent='修正報告の管理';footer.append(' · ',link);}adminSetup().catch(e=>{const status=document.getElementById('reports-admin-status');if(status)status.textContent=e.message;});}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ready,{once:true});else ready();
})();
